import React from 'react';

export default function Hero() {
  return (
    <div style={{
      background: 'linear-gradient(135deg, #0056b3 0%, #002d62 100%)',
      color: '#ffffff',
      padding: '100px 20px',
      textAlign: 'center',
      boxShadow: 'inset 0 -10px 20px rgba(0,0,0,0.1)'
    }}>
      <h1 style={{ fontSize: '42px', marginBottom: '20px', fontWeight: 'bold' }}>
        AuraPen Saku Education Institute
      </h1>
      <p style={{ fontSize: '18px', marginBottom: '40px', color: '#e0e0e0', maxWidth: '600px', marginLeft: 'auto', marginRight: 'auto', lineHeight: '1.6' }}>
        Welcome to AuraPen Saku Education Institute. Shaping the future through digital learning. Explore our courses and start your journey today.
      </p>
      <div>
        <button style={{
          padding: '14px 30px', fontSize: '16px', fontWeight: 'bold', color: '#0056b3', backgroundColor: '#ffffff',
          border: 'none', borderRadius: '30px', cursor: 'pointer', boxShadow: '0 4px 15px rgba(0,0,0,0.2)', marginRight: '15px'
        }}>
          Explore Courses
        </button>
        <button style={{
          padding: '14px 30px', fontSize: '16px', fontWeight: 'bold', color: '#ffffff', backgroundColor: 'transparent',
          border: '2px solid #ffffff', borderRadius: '30px', cursor: 'pointer'
        }}>
          Contact Us
        </button>
      </div>
    </div>
  );
}
